    let (sender, _receiver) = UnixDatagram::pair().unwrap();
    // The descriptor itself is deliberately blocking. MSG_DONTWAIT must still
    // make each individual export nonblocking.
    let sample = frame();
    let mut full = false;
    for _ in 0..1024 {
