use std::os::unix::fs::{symlink, DirBuilderExt};
use std::sync::atomic::{AtomicU64, Ordering};

static NEXT_DIRECTORY: AtomicU64 = AtomicU64::new(0);

struct Fixture {
    directory: PathBuf,
    directory_identity: Identity,
    path: PathBuf,
    socket_identity: Identity,
    _receiver: UnixDatagram,
}

impl Fixture {
    fn new() -> Self {
        let mut owned = None;
        for _ in 0..16 {
            let next = NEXT_DIRECTORY.fetch_add(1, Ordering::Relaxed);
            let path = PathBuf::from(format!(
                "/tmp/guard-native-phase-{}-{next}", std::process::id()
            ));
            match fs::DirBuilder::new().mode(0o700).create(&path) {
                Ok(()) => {
                    owned = Some(path);
                    break;
                }
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
                Err(error) => panic!("cannot create owned diagnostic fixture: {error}"),
            }
        }
        let directory = owned.expect("bounded diagnostic fixture names exhausted");
        let path = directory.join("phase.sock");
        let receiver = UnixDatagram::bind(&path).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(0o600)).unwrap();
        Self {
            directory_identity: identity(&directory, true).unwrap(),
            socket_identity: identity(&path, false).unwrap(),
            directory,
            path,
            _receiver: receiver,
        }
    }

    fn acquire(&self) -> Option<UnixDatagram> {
        acquire(&self.path, self.socket_identity.device, self.socket_identity.inode)
    }
}

fn same_object(left: Identity, right: Identity) -> bool {
    (left.device, left.inode, left.uid) == (right.device, right.inode, right.uid)
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let Ok(parent) = fs::symlink_metadata(&self.directory) else { return };
        if !parent.is_dir() || !same_object(Identity::from_metadata(&parent), self.directory_identity) {
            return;
        }
        if let Ok(socket) = fs::symlink_metadata(&self.path) {
            if socket.file_type().is_socket()
                && same_object(Identity::from_metadata(&socket), self.socket_identity)
            {
                let _ = fs::remove_file(&self.path);
            }
        }
        // Only the exact newly created, now-empty directory is removed.
        let _ = fs::remove_dir(&self.directory);
    }
}

#[test]
fn private_endpoint_requires_exact_owned_socket_identity() {
    let fixture = Fixture::new();
    let socket = fixture.acquire().unwrap();
    assert_eq!(socket.peer_addr().unwrap().as_pathname(), Some(fixture.path.as_path()));
    assert!(acquire(&fixture.path, fixture.socket_identity.device, fixture.socket_identity.inode + 1).is_none());
    assert!(acquire(&fixture.path, fixture.socket_identity.device.wrapping_add(1), fixture.socket_identity.inode).is_none());
}

#[test]
fn directory_and_socket_modes_are_admission_boundaries() {
    let fixture = Fixture::new();
    fs::set_permissions(&fixture.directory, fs::Permissions::from_mode(0o755)).unwrap();
    assert!(fixture.acquire().is_none());
    fs::set_permissions(&fixture.directory, fs::Permissions::from_mode(0o700)).unwrap();
    fs::set_permissions(&fixture.path, fs::Permissions::from_mode(0o666)).unwrap();
    assert!(fixture.acquire().is_none());
    fs::set_permissions(&fixture.path, fs::Permissions::from_mode(0o600)).unwrap();
    assert!(fixture.acquire().is_some());
}

#[test]
fn symlink_endpoint_and_unadmitted_path_shapes_are_refused() {
    let fixture = Fixture::new();
    let second = Fixture::new();
    fs::remove_file(&second.path).unwrap();
    symlink(&fixture.path, &second.path).unwrap();
    assert!(acquire(&second.path, fixture.socket_identity.device, fixture.socket_identity.inode).is_none());
    fs::remove_file(&second.path).unwrap();
    assert!(acquire(Path::new("phase.sock"), 0, 0).is_none());
    assert!(acquire(&fixture.directory.join("../phase.sock"), 0, 0).is_none());
    assert!(acquire(&fixture.directory.join("other.sock"), 0, 0).is_none());
    assert!(acquire(Path::new("/tmp/phase.sock"), 0, 0).is_none());
}

#[test]
fn regular_file_cannot_stand_in_for_the_diagnostic_socket() {
    let fixture = Fixture::new();
    fs::remove_file(&fixture.path).unwrap();
    fs::write(&fixture.path, b"controlled nonsocket").unwrap();
    fs::set_permissions(&fixture.path, fs::Permissions::from_mode(0o600)).unwrap();
    assert!(fixture.acquire().is_none());
    fs::remove_file(&fixture.path).unwrap();
}

#[test]
fn startup_identity_parser_handles_comm_delimiters_and_refuses_ambiguity() {
    let stat = format!("{} (controlled ) name) S {} 777\n",
        std::process::id(), "0 ".repeat(18));
    assert_eq!(parse_start_ticks(stat.as_bytes(), std::process::id()), Some(777));
    assert!(parse_start_ticks(stat.as_bytes(), std::process::id().wrapping_add(1)).is_none());
    assert!(parse_start_ticks(b"123 (short) S 0", 123).is_none());
    let zero = stat.replace("777", "0");
    assert!(parse_start_ticks(zero.as_bytes(), std::process::id()).is_none());
    assert!(self_start_ticks().is_some());
}

scripts/native_slo_rust_phase_process.py.content:
"""Bounded Linux process witnesses for the native diagnostic receiver.

This binds a live, explicitly owned fixture descendant at observation time.
It is diagnostic attribution, not a general concurrent-process attestation.
No command line, path, environment or credential bytes enter exported reports.
"""

from __future__ import annotations

import hashlib
import os
import stat
from dataclasses import dataclass
from pathlib import Path

from scripts.native_slo_rust_phase_schema import ROLES

MAX_PROCESS_DEPTH = 16
MAX_EXECUTABLE_BYTES = 128 * 1024 * 1024


@dataclass(frozen=True)
class ProcessIdentity:
    pid: int
    parent: int
    group: int
    session: int
    start_ticks: int


def _refuse() -> None:
    raise ValueError("native_phase_process_refused")


def _read_at(directory: int, name: str, bound: int) -> bytes:
    descriptor = os.open(name, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW, dir_fd=directory)
    try:
        chunks: list[bytes] = []
        remaining = bound + 1
        while remaining:
            chunk = os.read(descriptor, min(remaining, 65536))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        value = b"".join(chunks)
        if len(value) > bound:
            _refuse()
        return value
    finally:
        os.close(descriptor)


def parse_stat(value: bytes, expected_pid: int) -> ProcessIdentity:
    text = value.decode("utf-8")
    head, fields_text = text.rsplit(") ", 1)
    pid = int(head.split(" (", 1)[0])
    fields = fields_text.split()
    if pid != expected_pid or len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
        _refuse()
    row = ProcessIdentity(pid, int(fields[1]), int(fields[2]), int(fields[3]), int(fields[19]))
    if row.pid <= 0 or row.parent < 0 or row.group <= 0 or row.session <= 0 or row.start_ticks <= 0:
        _refuse()
    return row


def _same_executable(metadata: os.stat_result) -> tuple[int, int, int, int, int, int]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


class Executable:
    """Retain the exact caller-supplied binary descriptor and its source digest."""

    def __init__(self, path: Path) -> None:
        self.descriptor = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
        try:
            before = os.fstat(self.descriptor)
            if not stat.S_ISREG(before.st_mode) or not 0 < before.st_size <= MAX_EXECUTABLE_BYTES:
                _refuse()
            digest = hashlib.sha256()
            count = 0
            while True:
                chunk = os.read(self.descriptor, min(65536, MAX_EXECUTABLE_BYTES + 1 - count))
                if not chunk:
                    break
                count += len(chunk)
                digest.update(chunk)
                if count > MAX_EXECUTABLE_BYTES:
                    _refuse()
            self.identity = _same_executable(before)
            if count != before.st_size or _same_executable(os.fstat(self.descriptor)) != self.identity:
                _refuse()
            self.sha256 = digest.hexdigest()
        except BaseException:
            os.close(self.descriptor)
            self.descriptor = -1
            raise

    def current(self) -> bool:
        return self.descriptor >= 0 and _same_executable(os.fstat(self.descriptor)) == self.identity

    def close(self) -> None:
        if self.descriptor >= 0:
            os.close(self.descriptor)
            self.descriptor = -1


def read_process(pid: int, executable: Executable | None = None) -> tuple[ProcessIdentity, str | None]:
    if type(pid) is not int or not 1 <= pid <= 2**31 - 1:
        _refuse()
    directory = os.open(f"/proc/{pid}", os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        before = parse_stat(_read_at(directory, "stat", 4096), pid)
        status = _read_at(directory, "status", 65536).decode("ascii")
        uid_rows = [line.split()[1:] for line in status.splitlines() if line.startswith("Uid:")]
        gid_rows = [line.split()[1:] for line in status.splitlines() if line.startswith("Gid:")]
        if (
            len(uid_rows) != 1
            or len(gid_rows) != 1
            or uid_rows[0] != [str(os.geteuid())] * 4
            or gid_rows[0] != [str(os.getegid())] * 4
        ):
            _refuse()
        role = None
        if executable is not None:
            if not executable.current() or _same_executable(os.stat("exe", dir_fd=directory)) != executable.identity:
                _refuse()
            command = _read_at(directory, "cmdline", 16384)
            parts = command.split(b"\0")
            if len(parts) < 3 or parts[-1] != b"":
                _refuse()
            role = ROLES.get(parts[1].decode("ascii"))
            if role is None:
                _refuse()
        after = parse_stat(_read_at(directory, "stat", 4096), pid)
        if before != after:
            _refuse()
        if executable is not None and _same_executable(os.stat("exe", dir_fd=directory)) != executable.identity:
            _refuse()
        return before, role
    finally:
        os.close(directory)


class OwnedCohort:
    def __init__(self, fixture_pid: int, executable: Executable) -> None:
        root, _ = read_process(fixture_pid)
        if root.parent != os.getpid() or root.session != root.pid or root.group != root.pid:
            _refuse()
        self.root = root
        self.executable = executable
        self.seen: dict[int, tuple[int, str]] = {}

    def admit(self, pid: int, start_ticks: int, role: str) -> ProcessIdentity:
        sender, actual_role = read_process(pid, self.executable)
        if sender.start_ticks != start_ticks or actual_role != role:
            _refuse()
        if pid in self.seen and self.seen[pid] != (start_ticks, role):
            _refuse()
        if pid not in self.seen and len(self.seen) >= 16:
            _refuse()
        chain = [sender]
        for _ in range(MAX_PROCESS_DEPTH):
            current = chain[-1]
            if current.pid == self.root.pid:
                break
            if current.parent <= 1 or any(row.pid == current.parent for row in chain):
                _refuse()
            parent, _ = read_process(current.parent)
            if parent.start_ticks > current.start_ticks:
                _refuse()
            chain.append(parent)
        if chain[-1] != self.root:
            _refuse()
        # Re-read each exact process generation after walking the ancestry.
        # Any exit, reparenting or reuse makes this observation unavailable.
        for original in reversed(chain):
            current, _ = read_process(original.pid, self.executable if original.pid == sender.pid else None)
            if current != original:
                _refuse()
        self.seen[pid] = (start_ticks, role)
        return sender

scripts/native_slo_rust_phase_run.py.content:
"""Run the existing installed phase workload with optional Rust diagnostics.

The native binary must already be the exact installed runtime. This entry
point does not select an ingress, replace a binary, reuse a connection, alter a
deadline or extend native shutdown. All samples are diagnostic and incomplete.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any, cast

_ROOT = Path(__file__).resolve().parents[1]
if str(_ROOT) not in sys.path:
    sys.path.append(str(_ROOT))

from scripts.native_slo_daemon_fixture import DaemonFixture  # noqa: E402
from scripts.native_slo_phase_run import measure_installed_phases  # noqa: E402
from scripts.native_slo_rust_phase_receiver import NativePhaseReceiver, supported  # noqa: E402

_REQUIRED_PHASES = frozenset(
    {
        "client_connect_inclusive",
        "client_authenticate",
        "client_request_write_flush",
        "client_committed_response_read",
        "resident_evaluate_inclusive",
    }
)


def _observed_phases(native: dict[str, Any]) -> set[str]:
    return {
        phase["phase"]
        for process in native["processes"]
        if process["snapshot"] is not None
        for phase in process["snapshot"]["phases"]
        if phase["statistics"] is not None
    }


def measure_native_phases(runtime: Path, count: int, evidence_file: Path) -> dict[str, Any]:
    if type(count) is not int or not 1 <= count <= 100:
        raise ValueError("native_phase_count_outside_original_bound")
    result: dict[str, Any] = {
        "schema": "hol-guard-native-and-python-phase-run.v1",
        "scope": "diagnostic_instrumented_existing_installed_workload",
        "headline_timing_eligible": False,
        "qualification_complete": False,
        "complete_run": False,
        "status": "platform_unsupported",
        "workload_passed": False,
        "workload_failure_observed": False,
        "workload_started": False,
        "existing_fixture_failure_observed": False,
        "native_phase_error_observed": False,
        "original_phase_count_bound": 100,
        "requested_count_per_case": count,
        "original_semantic_workload": None,
        "native": None,
    }
    if not supported():
        return result
    receiver: NativePhaseReceiver | None = None
    try:
        receiver = NativePhaseReceiver(runtime)
    except Exception:
        result["native_phase_error_observed"] = True
    try:
        if receiver is not None:
            try:
                with DaemonFixture(
                    runtime, setup="normal", _native_phase_environment=receiver.environment()
                ) as session:
                    try:
                        receiver.attach(session.pid)
                    except Exception:
                        result["native_phase_error_observed"] = True
                    else:
                        result["workload_started"] = True
                        try:
                            result["original_semantic_workload"] = measure_installed_phases(
                                session, count, evidence_file
                            )
                            result["workload_passed"] = True
                        except Exception:
                            # The existing journal retains original failures;
                            # never export an exception or request value here.
                            result["workload_failure_observed"] = True
            except Exception:
                result["existing_fixture_failure_observed"] = True
    finally:
        if receiver is not None:
            try:
                receiver.close()
                result["native"] = receiver.report()
            except Exception:
                result["native_phase_error_observed"] = True
    native = cast(dict[str, Any] | None, result["native"])
    if result["existing_fixture_failure_observed"]:
        result["status"] = "existing_fixture_failed"
    elif result["workload_failure_observed"]:
        result["status"] = "workload_failed"
    elif not result["workload_started"]:
        result["status"] = "diagnostic_setup_failed"
    elif native is None or result["native_phase_error_observed"]:
        result["status"] = "diagnostic_incomplete"
    elif _REQUIRED_PHASES <= _observed_phases(native) and any(  # noqa: SIM300 - preserve operand evaluation order
        phase["phase"] in {"unix_socket_creation", "loopback_connect_handle"}
        and phase["statistics"] is not None
        and phase["statistics"]["returned_ok"] > 0
        for process in native["processes"]
        if process["snapshot"] is not None
        for phase in process["snapshot"]["phases"]
    ):
        result["status"] = "diagnostic_phases_observed"
    else:
        result["status"] = "diagnostic_incomplete"
    return result


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--runtime", type=Path, required=True)
    parser.add_argument("--count", type=int, default=1)
    parser.add_argument("--evidence-file", type=Path, required=True)
    parser.add_argument("--json", type=Path, required=True)
    arguments = parser.parse_args()
    report = measure_native_phases(arguments.runtime.resolve(strict=True), arguments.count, arguments.evidence_file)
    rendered = json.dumps(report, sort_keys=True, indent=2) + "\n"
    if len(rendered.encode("utf-8")) > 1024 * 1024:
        raise ValueError("native_phase_report_exceeded_bound")
    with arguments.json.open("x", encoding="utf-8") as output:
        output.write(rendered)
    print(
        json.dumps(
            {
                "schema": report["schema"],
                "status": report["status"],
                "headline_timing_eligible": False,
                "qualification_complete": False,
            },
            sort_keys=True,
        )
    )
    return 0 if report["status"] == "diagnostic_phases_observed" else 2


if __name__ == "__main__":
    raise SystemExit(main())

